static ABILITY_0_MODES: ModalDef = modes(&[mode(ability_0_mode_0, "Exile target artifact.").targets(ABILITY_0_MODE_0_TARGETS),mode(ability_0_mode_1, "Exile target enchantment.").targets(ABILITY_0_MODE_1_TARGETS),mode(ability_0_mode_2, "Manifest dread.").targets(&[])]).choose(1, 1);
fn announced(g: &dyn Game, item: &StackItem, spec: u8, legal: bool) -> Vec<Target> { (0..g.state().targets(item).len()).filter(|&i| g.state().spec(item, i) == spec && (!legal || g.target_legal(item, i))).map(|i| g.state().target(item, i)).collect() }

